package com.labloop.web;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.web.bind.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;
@SpringBootApplication public class LabLoopApplication{public static void main(String[]a){SpringApplication.run(LabLoopApplication.class,a);}}
@RestController @RequestMapping("/api") class Api{final JdbcTemplate db;Api(JdbcTemplate d){db=d;}@GetMapping("/equipment")Object all(){return db.queryForList("select * from equipment order by code");}@PostMapping("/equipment")Object add(@RequestBody Map<String,String>x){db.update("insert into equipment(code,name,category,status,condition_state,location)values(?,?,?,?,?,?)",x.get("code"),x.get("name"),x.get("category"),x.get("status"),x.get("condition"),x.get("location"));return Map.of("ok",true);}@DeleteMapping("/equipment/{id}")Object del(@PathVariable long id){db.update("delete from activity where equipment_id=?",id);db.update("delete from equipment where id=?",id);return Map.of("ok",true);}@PostMapping("/equipment/{id}/{a}")Object act(@PathVariable long id,@PathVariable String a,@RequestBody Map<String,String>x){String s=a.equals("borrow")?"BORROWED":a.equals("return")?"AVAILABLE":"MAINTENANCE";db.update("update equipment set status=?,condition_state=? where id=?",s,x.getOrDefault("condition","GOOD"),id);return Map.of("ok",true);}}
